import{c as t,Q as e,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"SetDequantType","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetDequantType","slug":"setdequanttype"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetDequantType.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetDequantType.md"}'),s={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetDequantType.md"};function i(p,a,u,o,r,c){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="setdequanttype" tabindex="-1">SetDequantType <a class="header-anchor" href="#setdequanttype" aria-label="Permalink to &quot;SetDequantType&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>该接口用于设置量化或反量化的模式。</p><p>Matmul反量化场景：在Matmul计算时，左、右矩阵的输入为int8_t或int4b_t类型，输出为half类型；或者左、右矩阵的输入为int8_t类型，输出为int8_t类型。该场景下，输出C矩阵的数据从CO1搬出到Global Memory时，会执行反量化操作，将最终结果反量化为对应的half或int8_t类型。</p><p>Matmul量化场景：在Matmul计算时，左、右矩阵的输入为half或bfloat16_t类型，输出为int8_t类型。该场景下，输出C矩阵的数据从CO1搬出到Global Memory时，会执行量化操作，将最终结果量化为int8_t类型。</p><p>量化或反量化时有两种模式：一种是同一系数的量化/反量化模式，一种是向量的量化/反量化模式。</p><ul><li>同一系数的量化或反量化模式：对输出矩阵的所有值采用同一系数进行量化或反量化。</li><li>向量的量化或反量化模式：提供一个参数向量，对输出矩阵的每一列都采用该向量中对应列的系数进行量化或反量化。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int32_t SetDequantType(DequantType dequantType)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dequantType</td><td>输入</td><td>设置量化或反量化时的模式。DequantType类型，该类型的定义如下方代码所示，其中参数的取值及含义如下： SCALAR：表示同一系数的量化或反量化模式。TENSOR：表示向量的量化或反量化模式。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum class DequantType {</span></span>
<span class="line"><span>    SCALAR = 0,</span></span>
<span class="line"><span>    TENSOR = 1,</span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>-1表示设置失败；0表示设置成功。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>本接口支持的同一系数的量化/反量化模式、向量的量化/反量化模式分别与Kernel侧接口<a href="./../../Matmul-Kernel侧接口/SetQuantScalar.html">SetQuantScalar</a>和<a href="./../../Matmul-Kernel侧接口/SetQuantVector.html">SetQuantVector</a>对应，本接口设置的量化/反量化模式必须与Kernel侧使用的接口保持一致。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT8);</span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT8);   </span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT32);   </span></span>
<span class="line"><span>tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_INT32);   </span></span>
<span class="line"><span>tiling.SetShape(M, N, K);   </span></span>
<span class="line"><span>tiling.SetOrgShape(M, N, K);</span></span>
<span class="line"><span>tiling.EnableBias(true);</span></span>
<span class="line"><span>tiling.SetDequantType(DequantType::SCALAR);  // 设置同一系数的量化/反量化模式</span></span>
<span class="line"><span>// tiling.SetDequantType(DequantType::TENSOR);</span><span>  // 设置向量的量化/反量化模式</span></span>
<span class="line"><span>tiling.SetBufferSpace(-1, -1, -1);</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int ret = tiling.GetTiling(tilingData);</span></span></code></pre></div>`,19)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
